REPORT_HTML_TEMPLATE = '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Отчёт ОП — F2B PRO</title>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js"></script>\n<style>\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif; background: #f8f7ff; color: #1e1b4b; min-height: 100vh; }\n.header { background: #fff; border-bottom: 1px solid #e8e5f5; padding: 14px 24px; display: flex; align-items: center; justify-content: space-between; }\n.header h1 { font-size: 17px; font-weight: 600; }\n.header .date { font-size: 13px; color: #6b7280; }\n.container { max-width: 1100px; margin: 0 auto; padding: 20px 16px; }\n.summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 10px; margin-bottom: 20px; }\n.card { background: #fff; border-radius: 10px; border: 1px solid #e8e5f5; padding: 12px 14px; }\n.card .label { font-size: 11px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.4px; margin-bottom: 5px; }\n.card .value { font-size: 20px; font-weight: 600; }\n.card .pct { font-size: 12px; margin-top: 3px; }\n.good { color: #059669; } .warn { color: #d97706; } .bad { color: #dc2626; }\n.charts-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 14px; margin-bottom: 20px; }\n.chart-wrap { background: #fff; border-radius: 10px; border: 1px solid #e8e5f5; padding: 16px; }\n.chart-label { font-size: 12px; font-weight: 500; color: #6b7280; text-transform: uppercase; letter-spacing: 0.4px; margin-bottom: 12px; }\n.mgr-tabs { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }\n.tab { padding: 7px 14px; border-radius: 18px; border: 1.5px solid #e8e5f5; background: #fff; cursor: pointer; font-size: 13px; font-weight: 500; color: #6b7280; transition: all 0.15s; }\n.tab.active { background: #7c3aed; border-color: #7c3aed; color: #fff; }\n.tab:hover:not(.active) { border-color: #a78bfa; color: #7c3aed; }\n.detail-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }\n.detail-card { background: #fff; border-radius: 10px; border: 1px solid #e8e5f5; padding: 16px; }\n.detail-card .dc-name { font-size: 14px; font-weight: 600; margin-bottom: 10px; padding-bottom: 8px; border-bottom: 1px solid #e8e5f5; }\n.dc-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 5px; font-size: 12px; }\n.dc-row .dl { color: #6b7280; }\n.dc-row .dv { font-weight: 500; }\n.bar-mini { height: 3px; background: #e8e5f5; border-radius: 2px; margin-bottom: 4px; }\n.bar-fill { height: 100%; border-radius: 2px; }\n.lost-badge { display: inline-block; background: #fef2f2; color: #dc2626; border-radius: 4px; padding: 2px 7px; font-size: 11px; font-weight: 600; margin-top: 6px; }\n.loading { text-align: center; padding: 60px 20px; color: #6b7280; }\n.spinner { width: 28px; height: 28px; border: 3px solid #e8e5f5; border-top-color: #7c3aed; border-radius: 50%; animation: spin 0.8s linear infinite; margin: 0 auto 12px; }\n@keyframes spin { to { transform: rotate(360deg); } }\n</style>\n</head>\n<body>\n<div class="header">\n  <h1>Отчёт ОП — F2B PRO</h1>\n  <span class="date" id="report-date"></span>\n</div>\n<div class="container">\n  <div id="loading" class="loading"><div class="spinner"></div>Загружаю данные...</div>\n  <div id="content" style="display:none">\n    <div class="summary" id="summary"></div>\n    <div class="mgr-tabs" id="tabs"></div>\n    <div class="charts-grid" id="charts"></div>\n    <div class="detail-grid" id="detail"></div>\n  </div>\n</div>\n<script>\nconst DATA = __REPORT_DATA__;\nconst MGR_COLORS = [\'#7c3aed\',\'#a855f7\',\'#c084fc\',\'#e879f9\'];\nconst METRICS = [\n  { key:\'revenue\',     label:\'Выручка\',      divisor:1e6, fmt: v => v.toFixed(1)+\' млн\' },\n  { key:\'shipments\',   label:\'Отгрузки\',      divisor:1,   fmt: v => Math.round(v)+\' шт\' },\n  { key:\'clients\',     label:\'АКБ\',           divisor:1,   fmt: v => Math.round(v)+\' кл\' },\n  { key:\'new_clients\', label:\'Новые клиенты\', divisor:1,   fmt: v => Math.round(v)+\' кл\' },\n  { key:\'attracted\',   label:\'Привл. товары\', divisor:1e6, fmt: v => v.toFixed(2)+\' млн\' },\n];\nlet charts = {};\nlet selectedMgr = \'all\';\nconst mgrs = Object.keys(DATA.facts);\nfunction pct(f,p){ return p ? Math.min(Math.round(f/p*100),999) : 0; }\nfunction pClass(p){ return p>=80?\'good\':p>=50?\'warn\':\'bad\'; }\nfunction getActiveMgrs(){ return selectedMgr===\'all\'?mgrs:[selectedMgr]; }\n\nfunction renderSummary(){\n  document.getElementById(\'summary\').innerHTML = METRICS.map(m => {\n    const tf = mgrs.reduce((s,mg)=>s+(DATA.facts[mg]?.[m.key]||0),0);\n    const tp = mgrs.reduce((s,mg)=>s+(DATA.plans[mg]?.[m.key]||0),0);\n    const p = pct(tf,tp);\n    return \'<div class="card"><div class="label">\'+m.label+\'</div><div class="value">\'+m.fmt(tf/m.divisor)+\'</div><div class="pct \'+pClass(p)+\'">\'+p+\'% из \'+m.fmt(tp/m.divisor)+\'</div></div>\';\n  }).join(\'\');\n}\n\nfunction renderTabs(){\n  const tabs = [[\'all\',\'Все\'],...mgrs.map(m=>[m,DATA.short_names[m]||m])];\n  document.getElementById(\'tabs\').innerHTML = tabs.map(([id,label])=>\n    \'<div class="tab \'+(id===selectedMgr?\'active\':\'\')+\'" onclick="selectMgr(\\\'\'+id+\'\\\')">\'+label+\'</div>\'\n  ).join(\'\');\n}\n\nfunction renderCharts(){\n  const am = getActiveMgrs();\n  const labels = am.map(m=>DATA.short_names[m]||m);\n  const colors = am.map((_,i)=>MGR_COLORS[i%MGR_COLORS.length]);\n  document.getElementById(\'charts\').innerHTML = METRICS.map((m,mi)=>\n    \'<div class="chart-wrap"><div class="chart-label">\'+m.label+\'</div><div style="position:relative;height:200px"><canvas id="chart_\'+mi+\'"></canvas></div></div>\'\n  ).join(\'\');\n  Object.values(charts).forEach(c=>c.destroy()); charts={};\n  METRICS.forEach((m,mi)=>{\n    const fData = am.map(mg=>{ const v=(DATA.facts[mg]?.[m.key]||0)/m.divisor; return m.divisor===1e6?Math.round(v*100)/100:Math.round(v); });\n    const pData = am.map(mg=>{ const v=(DATA.plans[mg]?.[m.key]||0)/m.divisor; return m.divisor===1e6?Math.round(v*100)/100:Math.round(v); });\n    charts[mi]=new Chart(document.getElementById(\'chart_\'+mi),{\n      type:\'bar\',\n      data:{ labels, datasets:[\n        { label:\'Факт\', data:fData, backgroundColor:colors.map(c=>c+\'bb\'), borderColor:colors, borderWidth:1, borderRadius:4 },\n        { label:\'План\', data:pData, type:\'line\', borderColor:colors.map(c=>c+\'66\'), borderWidth:1.5, borderDash:[4,3], pointRadius:4, pointBackgroundColor:colors, fill:false, tension:0 }\n      ]},\n      options:{ responsive:true, maintainAspectRatio:false,\n        plugins:{ legend:{display:false}, tooltip:{ callbacks:{ label:ctx=>(\' \'+(ctx.dataset.label===undefined?\'\':ctx.dataset.label)+\': \'+m.fmt(ctx.raw)) }}},\n        scales:{ x:{grid:{display:false},ticks:{font:{size:11}}}, y:{grid:{color:\'#f0effe\'},ticks:{font:{size:10},callback:v=>m.fmt(v)}} }\n      }\n    });\n  });\n}\n\nfunction renderDetail(){\n  const am = getActiveMgrs();\n  document.getElementById(\'detail\').innerHTML = am.map((mg,i)=>{\n    const f=DATA.facts[mg]||{}, p=DATA.plans[mg]||{};\n    const short=DATA.short_names[mg]||mg, color=MGR_COLORS[i%MGR_COLORS.length];\n    const lost=f.lost_clients||0;\n    const rows=METRICS.map(m=>{\n      const pc=pct(f[m.key]||0,p[m.key]||0);\n      return \'<div class="dc-row"><span class="dl">\'+m.label+\'</span><span class="dv \'+pClass(pc)+\'">\'+m.fmt((f[m.key]||0)/m.divisor)+\' / \'+m.fmt((p[m.key]||0)/m.divisor)+\'</span></div><div class="bar-mini"><div class="bar-fill" style="width:\'+Math.min(pc,100)+\'%;background:\'+color+\'"></div></div>\';\n    }).join(\'\');\n    return \'<div class="detail-card"><div class="dc-name" style="color:\'+color+\'">\'+short+\'</div>\'+rows+(lost>0?\'<span class="lost-badge">▼ выбыли: \'+lost+\'</span>\':\'\')+\'</div>\';\n  }).join(\'\');\n}\n\nfunction selectMgr(id){ selectedMgr=id; renderTabs(); renderCharts(); renderDetail(); }\n\ndocument.getElementById(\'report-date\').textContent=DATA.date;\ndocument.getElementById(\'loading\').style.display=\'none\';\ndocument.getElementById(\'content\').style.display=\'block\';\nrenderSummary(); renderTabs(); renderCharts(); renderDetail();\n</script>\n</body>\n</html>\n'
